head.script:
scwin.gVar = {
    "cTabIndex": "",
    "cTagName": "",
}




// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[checkcombobox > E > onblur]<br/>컴포넌트가 포커스를 잃을 때 발생합니다.",
    "validation" : [
        "컴포넌트가 포커스를 잃을 때 이벤트가 발생합니다.",
        "아이템 리스트창은 별도의 레이어로 처리되어 아이템 리스트창이 표시될때 컴포넌트에서 onblur 이벤트가 발생합니다.",
        "아이템 리스트창이 표시된 상태에서 포커스를 이동하면 onblur 이벤트가 발생하지 않습니다.",
    ]
}



scwin.wf_sample_onwframeload = function () {
    let wf_body_left = wf_sample.getObj("wf_body_left");
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let eList = $c.gcm.createEList(["onblur"]);

    // comp 생성 함수 호출    
    $c.gcm.createBasicCheckComboBox('', eList);  

    // 미지원 조건 비활성화
    wf_sample.getObj("con_tabIndex").setDisabled(true);  
    wf_sample.getObj("con_tagname").setDisabled(true);
    wf_sample.getObj("wf_body_sample").getObj("btn_createTarget").setDisabled(true);  
}
